args.command:
test -f ABSENT-SPEC.md; echo "ABSENT-SPEC exists=$?"; node --input-type=module - <<'EOF'
import { permit } from './limit.mjs';
const cases = [[-1,false],[0,true],[4,true],[5,false],[1.5,false],[NaN,false]];
for (const [input, expected] of cases) {
  const actual = permit(input);
  if (actual !== expected) throw new Error(`${input}: expected ${expected}, got ${actual}`);
}
console.log('permit smoke tests passed', cases.length);
EOF
